// Generated by allium:propagate from spec/recipe-import.allium (rule ReadRecipe: the per-member hourly drafts
// allowance, entity DraftRequest) and spec/recipe-ideas.allium (PickCandidate, UseOwnRecipe draw on the same
// allowance and touch the idea even when the import refuses). Do not edit by hand: change the spec and propagate.
import { describe, expect, it } from "vitest";
import type { RecipeIdea, RecipeIdeaId, Vocabulary } from "@weekly-planner/domain";
import type { RecipeIdeaRepository } from "../src/ports/recipe-ideas.js";
import type { DraftRequestLog, RecipeExtractor, RecipeSource, RecipeWriter } from "../src/ports/recipe-import.js";
import { NoteIdea, PickCandidate, UseOwnRecipe } from "../src/use-cases/recipe-ideas.js";
import { DraftRecipeImport } from "../src/use-cases/recipe-import.js";
import { AC, FakeClock, ME, SequenceIds } from "./support/in-memory.js";

const HOUR = 3_600_000;

type DraftRequestRow = Parameters<DraftRequestLog["add"]>[0];

class InMemoryDraftRequests implements DraftRequestLog {
  readonly all: DraftRequestRow[] = [];
  async add(request: DraftRequestRow) {
    this.all.push(request);
  }
  async listSince(from: number) {
    return this.all.filter((r) => r.requestedAt >= from);
  }
}

class InMemoryIdeas implements RecipeIdeaRepository {
  readonly byId = new Map<RecipeIdeaId, RecipeIdea>();
  async get(id: RecipeIdeaId) {
    return this.byId.get(id) ?? null;
  }
  async save(idea: RecipeIdea) {
    this.byId.set(idea.id, idea);
  }
  async remove(id: RecipeIdeaId) {
    this.byId.delete(id);
  }
  async listAll() {
    return [...this.byId.values()];
  }
}

/** Moves the fake clock forward by whole hours (it counts in hours of a day). */
const advance = (clock: FakeClock, ms: number) => {
  const target = clock.now() + ms;
  const d = new Date(target);
  clock.date = d.toISOString().slice(0, 10) as FakeClock["date"];
  clock.hour = d.getUTCHours();
  expect(clock.now()).toBe(target);
};

const vocabulary: Vocabulary = { items: ["Kürbis"], tags: [] };
const aRecipe = {
  name: "Kürbisgnocchi",
  steps: ["Kochen."],
  ingredients: [{ name: "Kürbis", amount: "500 g" }],
  mealType: "main",
  base: "other",
  diet: "vegetarian",
  tags: [],
};

function harness(config?: { maxDraftsPerHour: number }) {
  const requests = new InMemoryDraftRequests();
  const clock = new FakeClock();
  const extracted: string[] = [];
  const pages = new Map<string, Awaited<ReturnType<RecipeSource["read"]>>>();
  const source: RecipeSource = {
    read: async (address) => pages.get(address) ?? { ok: true, text: `Rezept auf ${address}` },
  };
  let extractorAnswer: () => unknown = () => aRecipe;
  const extractor: RecipeExtractor = {
    extract: async (text) => {
      extracted.push(text);
      return extractorAnswer();
    },
  };
  const writer: RecipeWriter = {
    vocabulary: async () => vocabulary,
    create: async () => ({ recipeId: 1, photoAttached: false }),
  };
  const deps = { source, extractor, writer, requests, clock };
  const draft = config === undefined ? new DraftRecipeImport(deps) : new DraftRecipeImport(deps, config);
  const ideas = new InMemoryIdeas();
  return {
    requests,
    clock,
    extracted,
    pages,
    answerWith: (f: () => unknown) => {
      extractorAnswer = f;
    },
    draft,
    ideas,
    note: new NoteIdea({ ideas, clock, ids: new SequenceIds() }),
    pick: new PickCandidate({ ideas, clock, draft }),
    own: new UseOwnRecipe({ ideas, clock, draft }),
  };
}

/** An idea with two candidates, noted two hours before now. */
async function anIdeaWithCandidates(h: ReturnType<typeof harness>) {
  const noted = await h.note.execute({ member: ME, title: "Kürbis" });
  if (!noted.ok) throw new Error(noted.reason);
  const idea: RecipeIdea = {
    ...noted.value,
    candidates: [
      { title: "Kürbisgnocchi", link: "https://example.org/gnocchi", summary: "" },
      { title: "Ofenkürbis", link: "https://example.org/ofen", summary: "" },
    ],
  };
  await h.ideas.save(idea);
  advance(h.clock, 2 * HOUR);
  return idea;
}

describe("ReadRecipe: DraftRequest", () => {
  it("records a draft a member asked for, from pasted text and from a link", async () => {
    const h = harness();
    expect((await h.draft.execute({ member: ME, text: "Kürbis schälen ..." })).ok).toBe(true);
    advance(h.clock, HOUR);
    expect((await h.draft.execute({ member: AC, address: "https://example.org/r" })).ok).toBe(true);
    expect(h.requests.all).toEqual([
      { requestedBy: ME, requestedAt: h.clock.now() - HOUR },
      { requestedBy: AC, requestedAt: h.clock.now() },
    ]);
  });

  it("records the draft even when the model's answer is then not a recipe (CheckDraft refuses it)", async () => {
    const h = harness();
    h.answerWith(() => ({ ...aRecipe, steps: [] }));
    expect((await h.draft.execute({ member: ME, text: "Kürbis schälen ..." })).ok).toBe(false);
    expect(h.requests.all).toEqual([{ requestedBy: ME, requestedAt: h.clock.now() }]);
  });

  it("records nothing when the source is refused before the model is asked", async () => {
    const h = harness();
    h.pages.set("http://127.0.0.1/x", { ok: false, reason: "address_not_public" });
    h.pages.set("https://example.org/empty", { ok: false, reason: "empty" });
    expect(await h.draft.execute({ member: ME, address: "http://127.0.0.1/x" })).toEqual({
      ok: false,
      reason: "address_not_public",
    });
    expect((await h.draft.execute({ member: ME, address: "https://example.org/empty" })).ok).toBe(false);
    expect(await h.draft.execute({ member: ME })).toEqual({ ok: false, reason: "need_one_source" });
    expect((await h.draft.execute({ member: ME, text: "   " })).ok).toBe(false);
    expect(h.extracted).toEqual([]);
    expect(h.requests.all).toEqual([]);
  });
});

describe("ReadRecipe: the hourly drafts allowance", () => {
  it("allows 20 drafts per member and hour by default", async () => {
    const h = harness();
    for (let i = 0; i < 20; i++) expect((await h.draft.execute({ member: ME, text: `Rezept ${i}` })).ok).toBe(true);
    expect(await h.draft.execute({ member: ME, text: "noch eins" })).toEqual({ ok: false, reason: "rate_limited" });
    expect(h.extracted).toHaveLength(20);
    expect(h.requests.all).toHaveLength(20);
  });

  it("refuses a member past the allowance and changes nothing: no draft, no DraftRequest, no model asked", async () => {
    const h = harness({ maxDraftsPerHour: 2 });
    expect((await h.draft.execute({ member: ME, text: "eins" })).ok).toBe(true);
    expect((await h.draft.execute({ member: ME, address: "https://example.org/zwei" })).ok).toBe(true);
    const before = [...h.requests.all];
    expect(await h.draft.execute({ member: ME, text: "drei" })).toEqual({ ok: false, reason: "rate_limited" });
    expect(await h.draft.execute({ member: ME, address: "https://example.org/vier" })).toEqual({
      ok: false,
      reason: "rate_limited",
    });
    expect(h.extracted).toEqual(["eins", "Rezept auf https://example.org/zwei"]);
    expect(h.requests.all).toEqual(before);
  });

  it("counts each member on their own", async () => {
    const h = harness({ maxDraftsPerHour: 1 });
    expect((await h.draft.execute({ member: ME, text: "eins" })).ok).toBe(true);
    expect((await h.draft.execute({ member: AC, text: "eins" })).ok).toBe(true);
    expect(await h.draft.execute({ member: ME, text: "zwei" })).toEqual({ ok: false, reason: "rate_limited" });
  });

  it("frees a draft from the count exactly an hour after it was asked for", async () => {
    const h = harness({ maxDraftsPerHour: 1 });
    expect((await h.draft.execute({ member: ME, text: "eins" })).ok).toBe(true);
    advance(h.clock, HOUR);
    expect((await h.draft.execute({ member: ME, text: "zwei" })).ok).toBe(true);
  });

  it("does not count refused attempts against the allowance", async () => {
    const h = harness({ maxDraftsPerHour: 1 });
    h.pages.set("http://10.0.0.1/x", { ok: false, reason: "address_not_public" });
    for (let i = 0; i < 3; i++) await h.draft.execute({ member: ME, address: "http://10.0.0.1/x" });
    await h.draft.execute({ member: ME });
    expect((await h.draft.execute({ member: ME, text: "eins" })).ok).toBe(true);
  });
});

describe("The drafts allowance is shared by the Import tab, PickCandidate and UseOwnRecipe", () => {
  it("counts picks and own sources like drafts from the Import tab", async () => {
    const h = harness({ maxDraftsPerHour: 3 });
    const idea = await anIdeaWithCandidates(h);
    expect((await h.draft.execute({ member: ME, text: "vom Import-Tab" })).ok).toBe(true);
    expect((await h.pick.execute({ member: ME, idea: idea.id, candidate: 0 })).ok).toBe(true);
    expect((await h.own.execute({ member: ME, idea: idea.id, text: "mein Rezept" })).ok).toBe(true);
    expect(h.requests.all.map((r) => r.requestedBy)).toEqual([ME, ME, ME]);
    expect(await h.draft.execute({ member: ME, text: "vom Import-Tab" })).toEqual({
      ok: false,
      reason: "rate_limited",
    });
  });

  it("refuses a pick past the allowance, but the pick still touches the idea", async () => {
    const h = harness({ maxDraftsPerHour: 1 });
    const idea = await anIdeaWithCandidates(h);
    expect((await h.draft.execute({ member: ME, text: "vom Import-Tab" })).ok).toBe(true);
    expect(await h.pick.execute({ member: ME, idea: idea.id, candidate: 1 })).toEqual({
      ok: false,
      reason: "rate_limited",
    });
    const after = await h.ideas.get(idea.id);
    expect(after?.lastTouchedAt).toBe(h.clock.now());
    expect(after?.candidates).toEqual(idea.candidates);
    expect(h.requests.all).toHaveLength(1);
    expect(h.extracted).toEqual(["vom Import-Tab"]);
  });

  it("refuses an own source past the allowance, but it still touches the idea", async () => {
    const h = harness({ maxDraftsPerHour: 1 });
    const idea = await anIdeaWithCandidates(h);
    expect((await h.draft.execute({ member: ME, text: "vom Import-Tab" })).ok).toBe(true);
    expect(await h.own.execute({ member: ME, idea: idea.id, address: "https://example.org/mine" })).toEqual({
      ok: false,
      reason: "rate_limited",
    });
    expect((await h.ideas.get(idea.id))?.lastTouchedAt).toBe(h.clock.now());
    expect(h.requests.all).toHaveLength(1);
  });

  it("touches the idea on a pick whose link the import refuses as unsafe, and records no draft", async () => {
    const h = harness();
    const idea = await anIdeaWithCandidates(h);
    h.pages.set("https://example.org/gnocchi", { ok: false, reason: "address_not_public" });
    expect(await h.pick.execute({ member: AC, idea: idea.id, candidate: 0 })).toEqual({
      ok: false,
      reason: "address_not_public",
    });
    expect((await h.ideas.get(idea.id))?.lastTouchedAt).toBe(h.clock.now());
    expect(h.requests.all).toEqual([]);
  });
});
